        case .ride: CGRect(x: 2.1, y: 4.1, width: 95.8, height: 95.8)
        case .cowbell: CGRect(x: -2.15, y: -4.65, width: 104.3, height: 104.3)
        case .snare: CGRect(x: 3.35, y: -3.65, width: 93.3, height: 93.3)
