// DRUM-ICON-DATA:END

/// The pictogram, square, filling whatever space it is given.
///
/// Line weight and the shell letter scale with the drawing so the whole pad reads as one set: the design reference
/// is 1.8 pt of stroke on a 38 pt icon. Sizing is left to the caller because the pad's keys share the row's width on
/// a phone, so a fixed size would overflow the narrowest ones.
struct DrumInstrumentIconView: View {
    let icon: DrumInstrumentIcon
    /// The shell letter (`H` / `M` / `L`), when the pad holds more than one drum of this kind.
    var label: String?

    @Environment(\.isEnabled) private var isEnabled

    var body: some View {
        GeometryReader { proxy in
            let side = min(proxy.size.width, proxy.size.height)
            ZStack {
                // Every layer names one fully-resolved colour. The filled hardware — the snare's lugs, the kick's
                // beater, the hi-hat's footboard — kept coming out at roughly a third opacity against a black
                // outline, and only on the pad: the same view inside the layout sheet drew it black. The pad's keys
                // are the difference. They are plain `Button`s wearing the automatic style, which restyles its
                // label, and `.primary` / `.foreground` are hierarchical — a filled shape under them can be
                // resolved a level down. `UIColor.label` is already a colour, so there is no level left to pick.
                if let fill = icon.fillPath {
                    DrumIconShape(commands: fill, viewBox: icon.viewBox).fill(ink)
                }
                DrumIconShape(commands: icon.strokePath, viewBox: icon.viewBox)
                    .stroke(ink, style: StrokeStyle(lineWidth: max(1, side * 0.047), lineCap: .round, lineJoin: .round))
                if let label, let anchor = icon.labelAnchor {
                    Text(label)
                        .font(.system(size: side * 0.28, weight: .bold))
                        .foregroundStyle(ink)
                        .position(place(anchor, in: proxy.size))
                }
            }
        }
        .aspectRatio(1, contentMode: .fit)
    }

    /// One colour for the whole drawing. The pad's key chrome dims a disabled key by dropping the foreground style
    /// to `.tertiary`; since the drawing opts out of inheriting that, it has to do the dimming itself.
    private var ink: Color {
        Color(uiColor: isEnabled ? .label : .tertiaryLabel)
    }

    /// A design-space point in the view's own coordinates. The shape scales uniformly and centres itself inside the
    /// view, so the label has to follow the same transform or it drifts off the shell as the icon resizes.
    private func place(_ point: CGPoint, in size: CGSize) -> CGPoint {
        let box = icon.viewBox
        let scale = min(size.width / box.width, size.height / box.height)
        return CGPoint(
            x: (size.width - box.width * scale) / 2 + (point.x - box.minX) * scale,
            y: (size.height - box.height * scale) / 2 + (point.y - box.minY) * scale,
        )
    }
}

/// Draws one normalized path string, mapping its view box onto the shape's rect.
private struct DrumIconShape: Shape {
    let commands: String
    let viewBox: CGRect

    func path(in rect: CGRect) -> Path {
        let scale = min(rect.width / viewBox.width, rect.height / viewBox.height)
        let originX = rect.minX + (rect.width - viewBox.width * scale) / 2
        let originY = rect.minY + (rect.height - viewBox.height * scale) / 2
        func point(_ x: Double, _ y: Double) -> CGPoint {
            CGPoint(x: originX + (x - viewBox.minX) * scale, y: originY + (y - viewBox.minY) * scale)
        }

        var path = Path()
        var numbers: [Double] = []
        var token = ""
        var command: Character?

        func flushNumber() {
            if let value = Double(token) {
                numbers.append(value)
            }
            token = ""
        }
        func flushCommand() {
            flushNumber()
            switch command {
            case "M" where numbers.count >= 2: path.move(to: point(numbers[0], numbers[1]))
            case "L" where numbers.count >= 2: path.addLine(to: point(numbers[0], numbers[1]))
            case "C" where numbers.count >= 6:
                path.addCurve(
                    to: point(numbers[4], numbers[5]),
                    control1: point(numbers[0], numbers[1]),
                    control2: point(numbers[2], numbers[3]),
                )
            case "Z": path.closeSubpath()
            default: break
            }
            numbers.removeAll(keepingCapacity: true)
        }

        for character in commands {
            if character.isLetter {
                flushCommand()
                command = character
            } else if character == " " {
                flushNumber()
            } else {
                token.append(character)
            }
        }
        flushCommand()
        return path
    }
}

